41	public class Gpx10FileLogger implements FileLogger {
42	    protected final static Object lock = new Object();
43	
44	    private final static ThreadPoolExecutor EXECUTOR = new ThreadPoolExecutor(1, 1, 60, TimeUnit.SECONDS,
45	            new LinkedBlockingQueue<Runnable>(10), new RejectionHandler());
46	    private File gpxFile = null;
47	    private final boolean addNewTrackSegment;
48	    protected final String name = "GPX";
49	
50	    public Gpx10FileLogger(File gpxFile, boolean addNewTrackSegment) {
51	        this.gpxFile = gpxFile;
52	        this.addNewTrackSegment = addNewTrackSegment;
53	    }
54	
55	    public void write(Location loc) throws Exception {
56	        long time = loc.getTime();
57	        if (time <= 0) {
58	            time = System.currentTimeMillis();
59	        }
60	        String dateTimeString = Strings.getIsoDateTime(new Date(time));
61	        if(PreferenceHelper.getInstance().shouldWriteTimeWithOffset()){
62	            dateTimeString = Strings.getIsoDateTimeWithOffset(new Date(time));
63	        }
64	
65	        Runnable writeHandler = getWriteHandler(dateTimeString, gpxFile, loc, addNewTrackSegment);
66	        EXECUTOR.execute(writeHandler);
67	    }
68	
69	    public Runnable getWriteHandler(String dateTimeString, File gpxFile, Location loc, boolean addNewTrackSegment)
70	    {
71	        return new Gpx10WriteHandler(dateTimeString, gpxFile, loc, addNewTrackSegment);
72	    }
73	
74	    public void annotate(String description, Location loc) throws Exception {
75	
76	        description = Strings.cleanDescriptionForXml(description);
77	
78	        long time = loc.getTime();
79	        if (time <= 0) {
80	            time = System.currentTimeMillis();
81	        }
82	        String dateTimeString = Strings.getIsoDateTime(new Date(time));
83	        if(PreferenceHelper.getInstance().shouldWriteTimeWithOffset()){
84	            dateTimeString = Strings.getIsoDateTimeWithOffset(new Date(time));
85	        }
86	
87	        Runnable annotateHandler = getAnnotateHandler(description, gpxFile, loc, dateTimeString);
88	        EXECUTOR.execute(annotateHandler);
89	    }
90	
91	    public Runnable getAnnotateHandler(String description, File gpxFile, Location loc, String dateTimeString){
92	        //Use the writer to calculate initial XML length, use that as offset for annotations
93	        Gpx10WriteHandler writer = (Gpx10WriteHandler)getWriteHandler(dateTimeString, gpxFile, loc, true);
94	        return new Gpx10AnnotateHandler(description, gpxFile, loc, dateTimeString, writer.getBeginningXml(dateTimeString).length());
95	    }
