194	class Gpx10WriteHandler implements Runnable {
195	    private static final Logger LOG = Logs.of(Gpx10WriteHandler.class);
196	    String dateTimeString;
197	    Location loc;
198	    private File gpxFile = null;
199	    private boolean addNewTrackSegment;
200	
201	    public Gpx10WriteHandler(String dateTimeString, File gpxFile, Location loc, boolean addNewTrackSegment) {
202	        this.dateTimeString = dateTimeString;
203	        this.addNewTrackSegment = addNewTrackSegment;
204	        this.gpxFile = gpxFile;
205	        this.loc = loc;
206	    }
207	
208	    @Override
209	    public void run() {
210	        synchronized (Gpx10FileLogger.lock) {
211	
212	            try {
213	                if (!Files.reallyExists(gpxFile)) {
214	                    gpxFile.createNewFile();
215	
216	                    FileOutputStream initialWriter = new FileOutputStream(gpxFile, true);
217	                    BufferedOutputStream initialOutput = new BufferedOutputStream(initialWriter);
218	
219	                    initialOutput.write(getBeginningXml(dateTimeString).getBytes());
220	                    initialOutput.write("<trk>".getBytes());
221	                    initialOutput.write("<name>".getBytes());
222	                    initialOutput.write(gpxFile.getName().replace(".gpx","").getBytes());
223	                    initialOutput.write("</name>".getBytes());
224	                    initialOutput.write(getEndXml().getBytes());
225	                    initialOutput.flush();
226	                    initialOutput.close();
227	
228	                    //New file, so new segment.
229	                    addNewTrackSegment = true;
230	                }
231	
232	                int offsetFromEnd = (addNewTrackSegment) ? getEndXml().length() : getEndXmlWithSegment().length();
233	                long startPosition = gpxFile.length() - offsetFromEnd;
234	                String trackPoint = getTrackPointXml(loc, dateTimeString);
235	
236	                RandomAccessFile raf = new RandomAccessFile(gpxFile, "rw");
237	                raf.seek(startPosition);
238	                raf.write(trackPoint.getBytes());
239	                raf.close();
240	                Files.addToMediaDatabase(gpxFile, "text/plain");
241	                LOG.debug("Finished writing to GPX10 file");
242	
243	            } catch (Exception e) {
244	                LOG.error("Gpx10FileLogger.write", e);
245	            }
246	
247	        }
248	
249	    }
250	
251	    String getBeginningXml(String dateTimeString){
252	        StringBuilder initialXml = new StringBuilder();
253	        initialXml.append("<?xml version=\"1.0\" encoding=\"UTF-8\" ?>");
254	        initialXml.append("<gpx version=\"1.0\" creator=\"GPSLogger " + BuildConfig.VERSION_CODE + " - http://gpslogger.mendhak.com/\" ");
255	        initialXml.append("xmlns:xsi=\"http://www.w3.org/2001/XMLSchema-instance\" ");
256	        initialXml.append("xmlns=\"http://www.topografix.com/GPX/1/0\" ");
257	        initialXml.append("xsi:schemaLocation=\"http://www.topografix.com/GPX/1/0 ");
258	        initialXml.append("http://www.topografix.com/GPX/1/0/gpx.xsd\">");
259	        initialXml.append("<time>").append(dateTimeString).append("</time>");
260	        return initialXml.toString();
261	    }
262	
263	    String getEndXml(){
264	        return "</trk></gpx>";
265	    }
266	
267	    String getEndXmlWithSegment(){
268	        return "</trkseg></trk></gpx>";
269	    }
270	
271	    String getTrackPointXml(Location loc, String dateTimeString) {
272	
273	        StringBuilder track = new StringBuilder();
274	
275	        if (addNewTrackSegment) {
276	            track.append("<trkseg>");
277	        }
278	
279	        track.append("<trkpt lat=\"")
280	                .append(String.valueOf(loc.getLatitude()))
281	                .append("\" lon=\"")
282	                .append(String.valueOf(loc.getLongitude()))
283	                .append("\">");
284	
285	        if (loc.hasAltitude()) {
286	            track.append("<ele>").append(String.valueOf(loc.getAltitude())).append("</ele>");
287	        }
288	
289	        track.append("<time>").append(dateTimeString).append("</time>");
290	
291	        appendCourseAndSpeed(track, loc);
292	
293	        if (loc.getExtras() != null) {
294	            String geoidheight = loc.getExtras().getString(BundleConstants.GEOIDHEIGHT);
295	
296	            if (!Strings.isNullOrEmpty(geoidheight)) {
297	                track.append("<geoidheight>").append(geoidheight).append("</geoidheight>");
298	            }
299	        }
300	
301	        track.append("<src>").append(loc.getProvider()).append("</src>");
302	
303	        if (loc.getExtras() != null) {
304	
305	            int sat = Maths.getBundledSatelliteCount(loc);
306	
307	            if(sat > 0){
308	                track.append("<sat>").append(String.valueOf(sat)).append("</sat>");
309	            }
310	
311	
312	            String hdop = loc.getExtras().getString(BundleConstants.HDOP);
313	            String pdop = loc.getExtras().getString(BundleConstants.PDOP);
314	            String vdop = loc.getExtras().getString(BundleConstants.VDOP);
315	            String ageofdgpsdata = loc.getExtras().getString(BundleConstants.AGEOFDGPSDATA);
316	            String dgpsid = loc.getExtras().getString(BundleConstants.DGPSID);
317	
318	            if (!Strings.isNullOrEmpty(hdop)) {
319	                track.append("<hdop>").append(hdop).append("</hdop>");
320	            }
321	
322	            if (!Strings.isNullOrEmpty(vdop)) {
323	                track.append("<vdop>").append(vdop).append("</vdop>");
324	            }
325	
326	            if (!Strings.isNullOrEmpty(pdop)) {
327	                track.append("<pdop>").append(pdop).append("</pdop>");
328	            }
329	
330	            if (!Strings.isNullOrEmpty(ageofdgpsdata)) {
331	                track.append("<ageofdgpsdata>").append(ageofdgpsdata).append("</ageofdgpsdata>");
332	            }
333	
334	            if (!Strings.isNullOrEmpty(dgpsid)) {
335	                track.append("<dgpsid>").append(dgpsid).append("</dgpsid>");
336	            }
337	        }
338	
339	
340	        track.append("</trkpt>\n");
341	
342	        track.append("</trkseg></trk></gpx>");
343	
344	        return track.toString();
345	    }
346	
347	    public void appendCourseAndSpeed(StringBuilder track, Location loc)
348	    {
349	        if (loc.hasBearing()) {
350	            track.append("<course>").append(String.valueOf(loc.getBearing())).append("</course>");
351	        }
352	
353	        if (loc.hasSpeed()) {
354	            track.append("<speed>").append(String.valueOf(loc.getSpeed())).append("</speed>");
355	        }
356	    }
357	}

