67	     * @return
68	     */
69	    public static String getMimeTypeFromFileName(String fileName) {
70	        if (fileName.endsWith("kml")) {
71	            return "application/vnd.google-earth.kml+xml";
72	        }
73	
74	        if (fileName.endsWith("gpx")) {
75	            return "application/gpx+xml";
76	        }
77	
78	        if (fileName.endsWith("zip")) {
79	            return "application/zip";
80	        }
81	
82	        if (fileName.endsWith("xml")) {
83	            return "application/xml";
84	        }
85	
86	        if (fileName.endsWith("nmea") || fileName.endsWith("txt")) {
87	            return "text/plain";
88	        }
89	
90	        if (fileName.endsWith("geojson")) {
91	            return "application/vnd.geo+json";
92	        }
93	
94	        if (fileName.endsWith("csv")){
95	            return "application/vnd.google-apps.spreadsheet";
96	        }
97	
98	        return "application/octet-stream";
99	
100	    }
