209	    public static void copyFile(File sourceLocation, File targetLocation)
210	            throws FileNotFoundException, IOException {
211	        InputStream in = new FileInputStream(sourceLocation);
212	        OutputStream out = new FileOutputStream(targetLocation);
213	
214	        // Copy the bits from instream to outstream
215	        byte[] buf = new byte[1024];
216	        int len;
217	        while ((len = in.read(buf)) > 0) {
218	            out.write(buf, 0, len);
219	        }
220	        in.close();
221	        out.close();
222	    }
