325	     * For a given File URI of the file:// format, get the corresponding Document URI in the content:// format.
326	     */
327	    @RequiresApi(Build.VERSION_CODES.R)
328	    private static Uri getDocumentUriFromFileUri(Context context, File file) {
329	        String filePath = file.getAbsolutePath();
330	        String volumeName = getVolumeName(context, file);
331	
332	        if(volumeName.equalsIgnoreCase("primary")){
333	            filePath = filePath.replace(Environment.getExternalStorageDirectory().getAbsolutePath(), "");
334	        }
335	        else {
336	            filePath = filePath.replace("/storage/"+volumeName, "");
337	        }
338	
339	        // Create the document URI with the content:// scheme.
340	        Uri documentUri = DocumentsContract.buildDocumentUri("com.android.externalstorage.documents", volumeName + ":" + filePath); //file.getAbsolutePath().substring(1)
341	
342	        return documentUri;
343	    }
