345	    @RequiresApi(Build.VERSION_CODES.R)
346	    private static String getVolumeName(Context context, File file) {
347	        String volumeName = null;
348	
349	        // Get the external storage volumes
350	        StorageManager storageManager = (StorageManager) context.getSystemService(Context.STORAGE_SERVICE);
351	        StorageVolume[] storageVolumes = storageManager.getStorageVolumes().toArray(new StorageVolume[0]);
352	
353	        // Go through all the volumes, find the volume for the given file
354	        for (StorageVolume storageVolume : storageVolumes) {
355	            String path = file.getAbsolutePath();
356	            String volumePath = storageVolume.getDirectory().getAbsolutePath();
357	            if (path.startsWith(volumePath)) {
358	                volumeName = storageVolume.getUuid();
359	                break;
360	            }
361	        }
362	
363	        // If the volume name is null, use the primary volume
364	        if (volumeName == null) {
365	            volumeName = "primary";
366	        }
367	
368	        return volumeName;
369	    }
