94	    public void requestToggleLogging() {
95	
96	        if(!Systems.locationPermissionsGranted(getActivity())){
97	            Dialogs.alert(getString(R.string.gpslogger_permissions_rationale_title),
98	                    getString(R.string.gpslogger_permissions_permanently_denied), getActivity());
99	            return;
100	        }
101	
102	        if (session.isStarted()) {
103	            toggleLogging();
104	            return;
105	        }
106	
107	        if(! Files.isAllowedToWriteTo(preferenceHelper.getGpsLoggerFolder())){
108	            Dialogs.alert(getString(R.string.error),getString(R.string.pref_logging_file_no_permissions) + "<br />" + preferenceHelper.getGpsLoggerFolder(), getActivity());
109	            return;
110	        }
111	
112	        ArrayList<FormElement> formElements = new ArrayList<>();
113	
114	        //If the user needs to be prompted about custom file name, build some form elements for it.
115	        if (preferenceHelper.shouldCreateCustomFile() && preferenceHelper.shouldAskCustomFileNameEachTime()) {
116	            formElements.add(Hint.plain(R.string.new_file_custom_title));
117	            formElements.add(Hint.plain(R.string.new_file_custom_message));
118	
119	            final List<String> cachedList = Files.getListFromCacheFile(PreferenceNames.CUSTOM_FILE_NAME, getActivity());
120	            formElements.add(Input.plain(PreferenceNames.CUSTOM_FILE_NAME)
121	                    .required()
122	                    // Don't allow *, &, %, / or \ in the file name.
123	                    .validatePattern("^[^*/\\\\]+$", "Invalid file name")
124	                    .suggest(new ArrayList<>(cachedList))
125	                    .text(preferenceHelper.getCustomFileName())
126	            );
127	
128	        }
129	
130	        //If the user needs to be prompted about OpenStreetMap settings, build some form elements for it.
131	        if(preferenceHelper.isAutoSendEnabled()
132	                && preferenceHelper.isOsmAutoSendEnabled()
133	                && FileSenderFactory.getOsmSender().isAutoSendAvailable()){
134	            formElements.add(Hint.plain(R.string.osm_setup_title));
135	            formElements.addAll(Dialogs.getOpenStreetMapFormElementsForDialog(preferenceHelper));
136	        }
137	
138	        //If the user needs to be prompted about any of the above, it's time to show a dialog
139	        //The result is handled in GPSMainactivity onResult.
140	        if(formElements.size() > 0){
141	
142	            SimpleFormDialog.build()
143	                    .fields(formElements.toArray(new FormElement[0]))
144	                    .pos(R.string.btn_start_logging)
145	                    .show(getActivity(), "shouldpromptbeforelogging");
146	        }
147	        //Else it's just normal logging.
148	        else {
149	            if(!session.isStarted()){
150	                Intent serviceIntent = new Intent(getActivity().getApplicationContext(), GpsLoggingService.class);
151	                ContextCompat.startForegroundService(getActivity().getApplicationContext(), serviceIntent);
152	            }
153	            toggleLogging();
154	        }
155	    }
