422	    private void notifyByBroadcast(boolean loggingStarted) {
423	            LOG.debug("Sending a custom broadcast");
424	            String event = (loggingStarted) ? "started" : "stopped";
425	            Intent sendIntent = new Intent();
426	            sendIntent.setAction("com.mendhak.gpslogger.EVENT");
427	            sendIntent.putExtra("gpsloggerevent", event); // started, stopped
428	            sendIntent.putExtra("filename", session.getCurrentFormattedFileName());
429	            sendIntent.putExtra("startedtimestamp", session.getStartTimeStamp());
430	            sendIntent.putExtra("duration", (int) (System.currentTimeMillis() - session.getStartTimeStamp()) / 1000);
431	            sendIntent.putExtra("distance", session.getTotalTravelled());
432	
433	            sendBroadcast(sendIntent);
434	    }
