460	        session.setPreviousLocationInfo(null);
461	        session.setStarted(false);
462	        session.setUserStillSinceTimeStamp(0);
463	        session.setLatestTimeStamp(0);
464	        stopAbsoluteTimer();
465	        // Email log file before setting location info to null
466	        autoSendLogFileOnStop();
467	        cancelAlarm();
468	        session.setCurrentLocationInfo(null);
469	        session.setSinglePointMode(false);
470	        stopForeground(true);
