494	    private Notification getNotification() {
495	
496	        Intent stopLoggingIntent = new Intent(this, GpsLoggingService.class);
497	        stopLoggingIntent.setAction("NotificationButton_STOP");
498	        stopLoggingIntent.putExtra(IntentConstants.IMMEDIATE_STOP, true);
499	        PendingIntent piStop = PendingIntent.getService(this, 0, stopLoggingIntent, 0);
500	
501	        Intent annotateIntent = new Intent(this, NotificationAnnotationActivity.class);
502	        annotateIntent.setAction("com.mendhak.gpslogger.NOTIFICATION_BUTTON");
503	        PendingIntent piAnnotate = PendingIntent.getActivity(this,0, annotateIntent,0);
504	
505	        // What happens when the notification item is clicked
506	        Intent contentIntent = new Intent(this, GpsMainActivity.class);
507	
