/**
 * A log file could not be written to, which means the user's points are being lost.
 * Usually happens when storage permissions have been revoked, or the chosen folder
 * is no longer writable.
 */
public static class FileWriteFailure {
    public String fileName;
    public String message;
    public Throwable throwable;

    public FileWriteFailure(String fileName, Throwable throwable) {
        this(fileName, (throwable != null) ? throwable.getMessage() : null, throwable);
    }

    public FileWriteFailure(String fileName, String message, Throwable throwable) {
        this.fileName = (fileName != null) ? fileName : "";
        this.message = (message != null) ? message : "";
        this.throwable = throwable;
    }
}

