public static boolean isAllowedToWriteTo(String gpsLoggerFolder) {
    return new File(gpsLoggerFolder).canWrite();
}

/**
 * Announces, to whoever is listening, that a file could not be written to.
 * Writing happens on background threads, so failures (revoked permissions, unwritable
 * folders, full storage) would otherwise be silent and the user would lose their data
 * without ever knowing about it.
 *
 * @param file      the file that could not be written to, can be null
 * @param throwable the cause of the failure, can be null
 */
public static void notifyFileWriteFailure(File file, Throwable throwable) {
    notifyFileWriteFailure((file == null) ? "" : file.getName(), throwable);
}

public static void notifyFileWriteFailure(String fileName, Throwable throwable) {
    LOG.error("Could not write to file " + fileName, throwable);

    try {
        EventBus.getDefault().post(new ServiceEvents.FileWriteFailure(fileName, throwable));
    } catch (Throwable t) {
        //Never let the notification itself break the logging loop.
        LOG.error("Could not notify of the file writing failure", t);
    }
}

