/**
 * Shows a notification telling the user that a log file could not be written to.
 * Without this, failed writes are silent and the user's locations are lost without warning.
 */
private void showFileWriteFailureNotification(ServiceEvents.FileWriteFailure failure) {

    //Writing is attempted for every single point, so only nag every so often.
    long now = System.currentTimeMillis();
    if (lastFileErrorNotificationTime > 0 && (now - lastFileErrorNotificationTime) < FILE_ERROR_NOTIFICATION_INTERVAL) {
        return;
    }
    lastFileErrorNotificationTime = now;

    String fileName = Strings.isNullOrEmpty(failure.fileName)
            ? preferenceHelper.getGpsLoggerFolder()
            : failure.fileName;

    String contentTitle = getString(R.string.could_not_write_to_file);
    String contentText = getString(R.string.could_not_write_to_file_detail, fileName);

    if (!Strings.isNullOrEmpty(failure.message)) {
        contentText = contentText + "\r\n\r\n" + failure.message;
    }

    Intent contentIntent = new Intent(this, GpsMainActivity.class);
    TaskStackBuilder stackBuilder = TaskStackBuilder.create(this);
    stackBuilder.addNextIntent(contentIntent);
    PendingIntent pending = stackBuilder.getPendingIntent(FILE_ERROR_NOTIFICATION_ID, PendingIntent.FLAG_UPDATE_CURRENT);

    notificationManager = (NotificationManager) getSystemService(NOTIFICATION_SERVICE);

    if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
        NotificationChannel errorChannel = new NotificationChannel(FILE_ERROR_NOTIFICATION_CHANNEL,
                getString(R.string.could_not_write_to_file), NotificationManager.IMPORTANCE_HIGH);
        errorChannel.setShowBadge(true);
        notificationManager.createNotificationChannel(errorChannel);
    }

    Notification errorNotification = new NotificationCompat.Builder(getApplicationContext(), FILE_ERROR_NOTIFICATION_CHANNEL)
            .setSmallIcon(R.drawable.notification)
            .setLargeIcon(BitmapFactory.decodeResource(getResources(), R.mipmap.gpsloggericon3))
            .setPriority(NotificationCompat.PRIORITY_HIGH)
            .setCategory(NotificationCompat.CATEGORY_ERROR)
            .setVisibility(NotificationCompat.VISIBILITY_PUBLIC)
            .setContentTitle(contentTitle)
            .setContentText(contentText)
            .setStyle(new NotificationCompat.BigTextStyle().bigText(contentText).setBigContentTitle(contentTitle))
            .setAutoCancel(true)
            .setOnlyAlertOnce(false)
            .setContentIntent(pending)
            .build();

    notificationManager.notify(FILE_ERROR_NOTIFICATION_ID, errorNotification);
}

