105	class Gpx10AnnotateHandler implements Runnable {
106	    private static final Logger LOG = Logs.of(Gpx10AnnotateHandler.class);
107	    String description;
108	    File gpxFile;
109	    Location loc;
110	    String dateTimeString;
111	    int annotateOffset;
112	
113	    public Gpx10AnnotateHandler(String description, File gpxFile, Location loc, String dateTimeString, int annotateOffset) {
114	        this.description = description;
115	        this.gpxFile = gpxFile;
116	        this.loc = loc;
117	        this.dateTimeString = dateTimeString;
118	        this.annotateOffset = annotateOffset;
119	    }
120	
121	    @Override
122	    public void run() {
123	
124	        synchronized (Gpx10FileLogger.lock) {
125	            if(!Files.reallyExists(gpxFile)){
126	                return;
127	            }
128	
129	            String wpt = getWaypointXml(loc, dateTimeString, description);
130	
131	            try {
132	
133	                //write to a temp file, delete original file, move temp to original
134	                File gpxTempFile = new File(gpxFile.getAbsolutePath() + ".tmp");
135	
136	                BufferedInputStream bis = new BufferedInputStream(new FileInputStream(gpxFile));
137	                BufferedOutputStream bos = new BufferedOutputStream(new FileOutputStream(gpxTempFile));
138	
139	                int written = 0;
140	                int readSize;
141	                byte[] buffer = new byte[annotateOffset];
142	                while ((readSize = bis.read(buffer)) > 0) {
143	                    bos.write(buffer, 0, readSize);
144	                    written += readSize;
145	
146	                    System.out.println(written);
147	
148	                    if (written == annotateOffset) {
149	                        bos.write(wpt.getBytes());
150	                        buffer = new byte[20480];
151	                    }
152	
153	                }
154	
155	                bis.close();
156	                bos.close();
157	
158	                gpxFile.delete();
159	                gpxTempFile.renameTo(gpxFile);
160	
161	                LOG.debug("Finished annotation to GPX10 File");
162	            } catch (Exception e) {
163	                LOG.error("Gpx10FileLogger.annotate", e);
164	            }
165	
166	        }
167	    }
