73	class Kml22AnnotateHandler implements Runnable {
74	    private static final Logger LOG = Logs.of(Kml22AnnotateHandler.class);
75	    File kmlFile;
76	    String description;
77	    Location loc;
78	    int kmlAnnotationOffset = 258;
79	
80	    public Kml22AnnotateHandler(File kmlFile, String description, Location loc) {
81	        this.kmlFile = kmlFile;
82	        this.description = description;
83	        this.loc = loc;
84	    }
85	
86	
87	    @Override
88	    public void run() {
89	        if(!Files.reallyExists(kmlFile)){
90	            return;
91	        }
92	
93	        try {
94	            synchronized (Kml22FileLogger.lock) {
95	
96	                String descriptionNode = getPlacemarkXml(description, loc);
97	
98	
99	                RandomAccessFile r = new RandomAccessFile(kmlFile, "rw");
100	                File tmpFile = new File(kmlFile.getAbsolutePath() + "~");
101	                tmpFile.createNewFile();
102	                RandomAccessFile rtemp = new RandomAccessFile(tmpFile, "rw");
103	                long fileSize = r.length();
104	                FileChannel sourceChannel = r.getChannel();
105	                FileChannel targetChannel = rtemp.getChannel();
106	                sourceChannel.transferTo(kmlAnnotationOffset, (fileSize - kmlAnnotationOffset), targetChannel);
107	                sourceChannel.truncate(kmlAnnotationOffset);
108	                r.seek(kmlAnnotationOffset);
109	                r.write(descriptionNode.getBytes());
110	                long newOffset = r.getFilePointer();
111	                targetChannel.position(0L);
112	                sourceChannel.transferFrom(targetChannel, newOffset, (fileSize - kmlAnnotationOffset));
113	                sourceChannel.close();
114	                targetChannel.close();
115	                tmpFile.delete();
116	
117	
118	            }
119	        } catch (Exception e) {
120	            LOG.error("Kml22FileLogger.annotate", e);
121	        }
122	    }
123	
124	    String getPlacemarkXml(String description, Location loc) {
125	        StringBuilder descriptionNode = new StringBuilder();
126	        descriptionNode.append("\n<Placemark><name>");
127	        descriptionNode.append(description);
128	        descriptionNode.append("</name><Point><coordinates>");
129	        descriptionNode.append(String.valueOf(loc.getLongitude()));
130	        descriptionNode.append(",");
131	        descriptionNode.append(String.valueOf(loc.getLatitude()));
132	        descriptionNode.append(",");
133	        descriptionNode.append(String.valueOf(loc.getAltitude()));
134	        descriptionNode.append("</coordinates></Point></Placemark>\n");
135	
136	        return descriptionNode.toString();
137	    }
138	}
