140	class Kml22WriteHandler implements Runnable {
141	
142	    private static final Logger LOG = Logs.of(Kml22WriteHandler.class);
143	    boolean addNewTrackSegment;
144	    File kmlFile;
145	    Location loc;
146	
147	
148	    public Kml22WriteHandler(Location loc, File kmlFile, boolean addNewTrackSegment) {
149	
150	        this.loc = loc;
151	        this.kmlFile = kmlFile;
152	        this.addNewTrackSegment = addNewTrackSegment;
153	    }
154	
155	
156	    @Override
157	    public void run() {
158	        try {
159	
160	            RandomAccessFile raf;
161	
162	            String dateTimeString = Strings.getIsoDateTime(new Date(loc.getTime()));
163	            if(PreferenceHelper.getInstance().shouldWriteTimeWithOffset()){
164	                dateTimeString = Strings.getIsoDateTimeWithOffset(new Date(loc.getTime()));
165	            }
166	            String placemarkHead = "<Placemark>\n<gx:Track>\n";
167	            String placemarkTail = "</gx:Track>\n</Placemark></Document></kml>\n";
168	
169	            synchronized (Kml22FileLogger.lock) {
170	
171	                if(!Files.reallyExists(kmlFile)){
172	                    kmlFile.createNewFile();
173	
174	                    FileOutputStream initialWriter = new FileOutputStream(kmlFile, true);
175	                    BufferedOutputStream initialOutput = new BufferedOutputStream(initialWriter);
176	
177	                    StringBuilder initialXml = new StringBuilder();
178	                    initialXml.append("<?xml version=\"1.0\" encoding=\"UTF-8\"?>");
179	                    initialXml.append("<kml xmlns=\"http://www.opengis.net/kml/2.2\" ");
180	                    initialXml.append("xmlns:gx=\"http://www.google.com/kml/ext/2.2\" ");
181	                    initialXml.append("xmlns:kml=\"http://www.opengis.net/kml/2.2\" ");
182	                    initialXml.append("xmlns:atom=\"http://www.w3.org/2005/Atom\">");
183	                    initialXml.append("<Document>");
184	                    initialXml.append("<name>").append(dateTimeString).append("</name>\n");
185	
186	                    initialXml.append("</Document></kml>\n");
187	                    initialOutput.write(initialXml.toString().getBytes());
188	                    initialOutput.flush();
189	                    initialOutput.close();
190	
191	                    //New file, so new track segment
192	                    addNewTrackSegment = true;
193	                }
194	
195	
196	                if (addNewTrackSegment) {
197	                    raf = new RandomAccessFile(kmlFile, "rw");
198	                    raf.seek(kmlFile.length() - 18);
199	                    raf.write((placemarkHead + placemarkTail).getBytes());
200	                    raf.close();

200	                    raf.close();
201	
202	                }
203	
204	                StringBuilder coords = new StringBuilder();
205	                coords.append("\n<when>");
206	                coords.append(dateTimeString);
207	                coords.append("</when>\n<gx:coord>");
208	                coords.append(String.valueOf(loc.getLongitude()));
209	                coords.append(" ");
210	                coords.append(String.valueOf(loc.getLatitude()));
211	                coords.append(" ");
212	                coords.append(String.valueOf(loc.getAltitude()));
213	                coords.append("</gx:coord>\n");
214	                coords.append(placemarkTail);
215	
216	                raf = new RandomAccessFile(kmlFile, "rw");
217	                raf.seek(kmlFile.length() - 42);
218	                raf.write(coords.toString().getBytes());
219	                raf.close();
220	                Files.addToMediaDatabase(kmlFile, "text/xml");
221	                LOG.debug("Finished writing to KML22 File");
222	            }
223	
224	        } catch (Exception e) {
225	            LOG.error("Kml22FileLogger.write", e);
226	        }
227	    }
228	}
