68	        public static final String PROFILE_NAME = "profile_name";
69	        public static final String BATTERY_CHARGING = "battery_charging";
70	    }
71	
72	    private final Integer batteryLevel;
73	    private final boolean batteryCharging;
74	    private File file;
75	    protected final String name = "CSV";
76	
77	    public CSVFileLogger(File file, Context context) {
78	        this.file = file;
