91	    public static String[] getCSVFileHeaders(){
92	        return new String[]{
93	                CSVFileLogger.FIELDS.TIME,
94	                CSVFileLogger.FIELDS.LAT,
95	                CSVFileLogger.FIELDS.LON,
96	                CSVFileLogger.FIELDS.ELEVATION,
97	                CSVFileLogger.FIELDS.ACCURACY,
98	                CSVFileLogger.FIELDS.BEARING,
99	                CSVFileLogger.FIELDS.SPEED,
100	                CSVFileLogger.FIELDS.SATELLITES,
101	                CSVFileLogger.FIELDS.PROVIDER,
102	                CSVFileLogger.FIELDS.HDOP,
103	                CSVFileLogger.FIELDS.VDOP,
104	                CSVFileLogger.FIELDS.PDOP,
105	                CSVFileLogger.FIELDS.GEOID_HEIGHT,
106	                CSVFileLogger.FIELDS.AGE_OF_DGPS_DATA,
107	                CSVFileLogger.FIELDS.DGPS_ID,
108	                CSVFileLogger.FIELDS.ACTIVITY,
109	                CSVFileLogger.FIELDS.BATTERY,
110	                CSVFileLogger.FIELDS.ANNOTATION,
111	                CSVFileLogger.FIELDS.TIMESTAMP_MILLIS,
112	                CSVFileLogger.FIELDS.TIME_WITH_OFFSET,
113	                CSVFileLogger.FIELDS.DISTANCE,
114	                CSVFileLogger.FIELDS.START_TIMESTAMP_MILLIS,
115	                CSVFileLogger.FIELDS.PROFILE_NAME,
116	                CSVFileLogger.FIELDS.BATTERY_CHARGING
117	        };
118	    }
119	
120	    @Override
121	    public void annotate(String description, Location loc) throws Exception {
122	
123	        if(!Files.reallyExists(file)){
124	            CSVFormat header = CSVFormat.DEFAULT.builder()
125	                    .setHeader(getCSVFileHeaders())
126	                    .setDelimiter(PreferenceHelper.getInstance().getCSVDelimiter())
127	                    .build();
128	            FileWriter out = new FileWriter(file);
129	            CSVPrinter printer = new CSVPrinter(out, header);
130	            printer.close();
131	            out.close();
132	        }
133	
134	        CSVFormat header = CSVFormat.DEFAULT.builder().setSkipHeaderRecord(true)
135	                .setDelimiter(PreferenceHelper.getInstance().getCSVDelimiter())
136	                .build();
137	
138	        FileWriter out = new FileWriter(file, true);
139	        try (CSVPrinter printer = new CSVPrinter(out, header)) {
140	            printer.printRecord(
141	                    Strings.getIsoDateTime(new Date(loc.getTime())),
142	                    applyDecimalComma(loc.getLatitude()),
143	                    applyDecimalComma(loc.getLongitude()),
144	                    loc.hasAltitude() ? applyDecimalComma(loc.getAltitude()) : "",
145	                    loc.hasAccuracy() ? applyDecimalComma(loc.getAccuracy()) : "",
146	                    loc.hasBearing() ? applyDecimalComma(loc.getBearing()) : "",
147	                    loc.hasSpeed() ? applyDecimalComma(loc.getSpeed()) : "",
148	                    Maths.getBundledSatelliteCount(loc),
149	                    loc.getProvider(),
150	                    (loc.getExtras() != null && !Strings.isNullOrEmpty(loc.getExtras().getString(BundleConstants.HDOP))) ? applyDecimalComma(loc.getExtras().getString(BundleConstants.HDOP)) : "",
151	                    (loc.getExtras() != null && !Strings.isNullOrEmpty(loc.getExtras().getString(BundleConstants.VDOP))) ? applyDecimalComma(loc.getExtras().getString(BundleConstants.VDOP)) : "",
152	                    (loc.getExtras() != null && !Strings.isNullOrEmpty(loc.getExtras().getString(BundleConstants.PDOP))) ? applyDecimalComma(loc.getExtras().getString(BundleConstants.PDOP)) : "",
153	                    (loc.getExtras() != null && !Strings.isNullOrEmpty(loc.getExtras().getString(BundleConstants.GEOIDHEIGHT))) ? applyDecimalComma(loc.getExtras().getString(BundleConstants.GEOIDHEIGHT)) : "",
154	                    (loc.getExtras() != null && !Strings.isNullOrEmpty(loc.getExtras().getString(BundleConstants.AGEOFDGPSDATA))) ? loc.getExtras().getString(BundleConstants.AGEOFDGPSDATA) : "",
155	                    (loc.getExtras() != null && !Strings.isNullOrEmpty(loc.getExtras().getString(BundleConstants.DGPSID))) ? loc.getExtras().getString(BundleConstants.DGPSID) : "",
156	                    "", //Activity detection was removed, but keeping this here for backward compatibility.
157	                    (batteryLevel != null) ? batteryLevel : "",
158	                    description,
159	                    loc.getTime(),
160	                    Strings.getIsoDateTimeWithOffset(new Date(loc.getTime())),
161	                    applyDecimalComma(Session.getInstance().getTotalTravelled()),
162	                    Session.getInstance().getStartTimeStamp(),
163	                    PreferenceHelper.getInstance().getCurrentProfileName(),
164	                    batteryCharging
165	            );
166	        }
167	        out.close();
168	
169	        Files.addToMediaDatabase(file, "text/csv");
170	    }
171	
172	    /**
173	     * Apply user selected decimal comma, if that option was enabled.
174	     */
175	    private String applyDecimalComma(Object value) {
176	        String returnValue = String.valueOf(value);
177	        if(PreferenceHelper.getInstance().shouldCSVUseCommaInsteadOfPoint()){
178	            returnValue = returnValue.replace(".",",");
179	        }
180	        return returnValue;
181	    }
182	
183	    @Override
184	    public String getName() {
185	        return name;
186	    }
187	
188	}
