40	public class FileLoggerFactory {
41	
42	    private static PreferenceHelper preferenceHelper = PreferenceHelper.getInstance();
43	    private static Session session = Session.getInstance();
44	
45	    public static List<FileLogger> getFileLoggers(Context context) {
46	
47	        List<FileLogger> loggers = new ArrayList<>();
48	
49	        if(Strings.isNullOrEmpty(preferenceHelper.getGpsLoggerFolder())){
50	            return loggers;
51	        }
52	
53	        File gpxFolder = new File(preferenceHelper.getGpsLoggerFolder());
54	        if (!gpxFolder.exists()) {
55	            gpxFolder.mkdirs();
56	        }
57	
58	        if (preferenceHelper.shouldLogToGpx()) {
59	            File gpxFile = new File(gpxFolder.getPath(), Strings.getFormattedFileName() + ".gpx");
60	            if(preferenceHelper.shouldLogAsGpx11()) {
61	                loggers.add(new Gpx11FileLogger(gpxFile, session.shouldAddNewTrackSegment()));
62	            } else {
63	                loggers.add(new Gpx10FileLogger(gpxFile, session.shouldAddNewTrackSegment()));
64	            }
65	        }
66	
67	        if (preferenceHelper.shouldLogToKml()) {
68	            File kmlFile = new File(gpxFolder.getPath(), Strings.getFormattedFileName() + ".kml");
69	            loggers.add(new Kml22FileLogger(kmlFile, session.shouldAddNewTrackSegment()));
70	        }
71	
72	        if (preferenceHelper.shouldLogToCSV()) {
73	            File file = new File(gpxFolder.getPath(), Strings.getFormattedFileName() + ".csv");
74	            loggers.add(new CSVFileLogger(file, context));
75	        }
76	
77	        if (preferenceHelper.shouldLogToOpenGTS()) {
78	            loggers.add(new OpenGTSLogger(context));
79	        }
80	
81	        if (preferenceHelper.shouldLogToCustomUrl()) {
82	
83	            loggers.add(new CustomUrlLogger(preferenceHelper.getCustomLoggingUrl(),
84	                    context,
85	                    preferenceHelper.getCustomLoggingHTTPMethod(),
86	                    preferenceHelper.getCustomLoggingHTTPBody(),
87	                    preferenceHelper.getCustomLoggingHTTPHeaders(),
88	                    preferenceHelper.getCustomLoggingBasicAuthUsername(),
89	                    preferenceHelper.getCustomLoggingBasicAuthPassword()));
90	        }
91	
92	        if(preferenceHelper.shouldLogToGeoJSON()){
93	            File file = new File(gpxFolder.getPath(), Strings.getFormattedFileName() + ".geojson");
94	            loggers.add(new GeoJSONLogger(file, session.shouldAddNewTrackSegment()));
95	        }
96	
97	
98	        return loggers;
99	    }
100	
101	    public static void write(Context context, Location loc) throws Exception {
102	        for (FileLogger logger : getFileLoggers(context)) {
103	            logger.write(loc);
104	        }
105	    }
106	
107	    public static void annotate(Context context, String description, Location loc) throws Exception {
108	        for (FileLogger logger : getFileLoggers(context)) {
109	            logger.annotate(description, loc);
110	        }
111	    }
112	}
