75	    /**
76	     * Format the GeoJSON entry
77	     *
78	     * @param append False to prepend the GeoJSON header (initialize file), true to prepend a list dividing character
79	     * @return A formatted {@link String} to write at position -TRAILER_LENGTH (or 0 for a new file)
80	     */
81	    @NonNull
82	    protected String getString(boolean append) {
83	        String coords = String.format(COORD_TEMPLATE, location.getLongitude(), location.getLatitude());
84	        StringBuilder value = new StringBuilder();
85	        if (append) {
86	            value.append(DIVIDER);
87	        } else {
88	            value.append(HEADER);
89	        }
90	        String extra = "";
91	        StringBuilder attributes = new StringBuilder();
92	        attributes.append("\"time\":\"").append(dateTimeString).append("\"");
93	        attributes.append(String.format(ATTRIBUTE_TEMPLATE, "provider", location.getProvider()));
94	        attributes.append(String.format(NUMERIC_ATTRIBUTE_TEMPLATE, "time_long", location.getTime()));
95	        if (!Strings.isNullOrEmpty(desc)) {
96	            attributes.append(String.format(ATTRIBUTE_TEMPLATE, "description", Strings.cleanDescriptionForJson(desc)));
97	        }
98	        if (location.hasAccuracy()) {
99	            attributes.append(String.format(NUMERIC_ATTRIBUTE_TEMPLATE, "accuracy", location.getAccuracy()));
100	        }
101	        if (location.hasAltitude()) {
102	            attributes.append(String.format(NUMERIC_ATTRIBUTE_TEMPLATE, "altitude", location.getAltitude()));
103	        }
104	        if (location.hasBearing()) {
105	            attributes.append(String.format(NUMERIC_ATTRIBUTE_TEMPLATE, "bearing", location.getBearing()));
106	        }
107	        if (location.hasSpeed()) {
108	            attributes.append(String.format(NUMERIC_ATTRIBUTE_TEMPLATE, "speed", location.getSpeed()));
109	        }
110	
111	        extra = attributes.toString();
112	        value.append(String.format(TEMPLATE,
113	                extra,
114	                coords)).append(TRAILER);
115	        return value.toString();
116	    }
