49	public class CustomUrlJob extends Job {
50	
51	    private static final Logger LOG = Logs.of(CustomUrlJob.class);
52	
53	    private UploadEvents.BaseUploadEvent callbackEvent;
54	
55	    private File csvFile;
56	    private ArrayList<CustomUrlRequest> urlRequests;
57	
58	    public CustomUrlJob(ArrayList<CustomUrlRequest> urlRequests, File csvFile, UploadEvents.BaseUploadEvent callbackEvent) {
59	        super(new Params(1).requireNetwork().persist());
60	
61	        this.callbackEvent = callbackEvent;
62	        this.urlRequests = urlRequests;
63	        this.csvFile = csvFile;
64	    }
65	
66	    @Override
67	    public void onAdded() {
68	    }
69	
70	    @Override
71	    public void onRun() throws Throwable {
72	
73	        boolean success = true;
74	        String responseError = null;
75	        String responseThrowableMessage = null;
76	
77	        if(urlRequests != null && urlRequests.size() > 0){
78	
79	            for (CustomUrlRequest urlRequest : urlRequests) {
80	                LOG.info("HTTP Request - " + urlRequest.getLogURL());
81	
82	                OkHttpClient.Builder okBuilder = new OkHttpClient.Builder();
83	                okBuilder.sslSocketFactory(Networks.getSocketFactory(AppSettings.getInstance()),
84	                        (X509TrustManager) Networks.getTrustManager(AppSettings.getInstance()));
85	                Request.Builder requestBuilder = new Request.Builder().url(urlRequest.getLogURL());
86	
87	                for(Map.Entry<String,String> header : urlRequest.getHttpHeaders().entrySet()){
88	                    requestBuilder.addHeader(header.getKey(), header.getValue());
89	                }
90	
91	                if ( ! urlRequest.getHttpMethod().equalsIgnoreCase("GET")) {
92	                    RequestBody body = RequestBody.create(null, urlRequest.getHttpBody());
93	                    requestBuilder = requestBuilder.method(urlRequest.getHttpMethod(),body);
94	                }
95	
96	                Request request = requestBuilder.build();
97	                Response response = okBuilder.build().newCall(request).execute();
98	
99	                if (response.isSuccessful()) {
100	                    LOG.debug("HTTP request complete with successful response code " + response);
101	                }
102	                else {
103	                    LOG.error("HTTP request complete with unexpected response code " + response );
104	                    responseError = "Unexpected code " + response;
105	                    responseThrowableMessage = response.body().string();
106	                    success = false;
107	                }
108	
109	                response.body().close();
110	
111	                if(!success){
112	                    break;
113	                }
114	            }
115	        }
116	
117	        if(success){
118	            EventBus.getDefault().post(callbackEvent.succeeded());
119	        }
120	        else {
121	            EventBus.getDefault().post(callbackEvent.failed("Unexpected code " + responseError, new Throwable(responseThrowableMessage)));
122	        }
123	    }
124	
125	    @Override
126	    protected void onCancel(int cancelReason, @Nullable Throwable throwable) {
127	        EventBus.getDefault().post(callbackEvent.failed("Could not send to custom URL", throwable));
128	        LOG.error("Custom URL: maximum attempts failed, giving up", throwable);
129	    }
130	
131	    @Override
132	    protected RetryConstraint shouldReRunOnThrowable(@NonNull Throwable throwable, int runCount, int maxRunCount) {
133	        LOG.warn(String.format("Custom URL: attempt %d failed, maximum %d attempts", runCount, maxRunCount));
134	        return RetryConstraint.createExponentialBackoff(runCount, 5000);
135	    }
136	
137	
138	    @Override
139	    protected int getRetryLimit() {
140	        return 3;
141	    }
142	}
